const M={'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'yo','ж':'j','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'x','ц':'ts','ч':'ch','ш':'sh','щ':'sh','ъ':'’','ь':'','ы':'i','э':'e','ю':'yu','я':'ya','ў':'o‘','қ':'q','ғ':'g‘','ҳ':'h','ā':'ā','ӣ':'ī','ӯ':'ū'};
function lat(s){return s.replace(/<[^>]*>|[^<]+/g,seg=>{if(seg[0]==='<')return seg;let o='';for(let i=0;i<seg.length;i++){const c=seg[i],lc=c.toLowerCase(),up=c!==lc;let r=M[lc];if(r===undefined){o+=c;continue}
 if(lc==='е'){const p=seg[i-1]||' ';if(!/[а-яёўқғҳa-z]/i.test(p)||/[аеёиоуўэюя]/i.test(p))r='ye'}
 if(up&&r)r=(seg[i+1]&&seg[i+1]!==seg[i+1].toLowerCase())?r.toUpperCase():r[0].toUpperCase()+r.slice(1);o+=r}return o})}
window.I18N={T,LANGS,lat};
